-- database/migrations/001_initial_schema.sql
-- Lab Portal — Initial database schema
-- Run with: npm run migrate (in portal-backend directory)
-- Generated by: BACKEND_AGENT

-- Enable UUID generation
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ── users ────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS users (
  id            UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  email         VARCHAR(255) UNIQUE NOT NULL,
  username      VARCHAR(50)  UNIQUE NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  full_name     VARCHAR(255) NOT NULL,
  student_id    VARCHAR(50),
  role          VARCHAR(20)  NOT NULL DEFAULT 'student'
                  CHECK (role IN ('admin','instructor','student')),
  status        VARCHAR(20)  NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending','active','locked','deleted')),
  lab_slot      SMALLINT     UNIQUE CHECK (lab_slot BETWEEN 1 AND 20),
  created_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  last_login    TIMESTAMPTZ,
  approved_by   UUID         REFERENCES users(id),
  approved_at   TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_users_email  ON users(email);
CREATE INDEX IF NOT EXISTS idx_users_role   ON users(role);
CREATE INDEX IF NOT EXISTS idx_users_status ON users(status);
CREATE INDEX IF NOT EXISTS idx_users_slot   ON users(lab_slot);

-- ── refresh_tokens ───────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS refresh_tokens (
  id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash  VARCHAR(255) NOT NULL,
  expires_at  TIMESTAMPTZ NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  revoked_at  TIMESTAMPTZ,
  ip_address  INET,
  user_agent  TEXT
);

CREATE INDEX IF NOT EXISTS idx_refresh_user ON refresh_tokens(user_id);
CREATE INDEX IF NOT EXISTS idx_refresh_exp  ON refresh_tokens(expires_at);

-- ── lab_slots ────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS lab_slots (
  slot_number  SMALLINT    PRIMARY KEY CHECK (slot_number BETWEEN 1 AND 20),
  user_id      UUID        REFERENCES users(id) ON DELETE SET NULL,
  scenario_id  VARCHAR(100),
  status       VARCHAR(30) NOT NULL DEFAULT 'empty'
                 CHECK (status IN ('empty','deploying','running','error','destroying')),
  tf_workspace VARCHAR(100) UNIQUE,
  deployed_at  TIMESTAMPTZ,
  last_reset   TIMESTAMPTZ,
  deploy_log   TEXT
);

-- Pre-populate all 20 slots
INSERT INTO lab_slots (slot_number)
SELECT generate_series(1, 20)
ON CONFLICT (slot_number) DO NOTHING;

-- ── audit_log ────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS audit_log (
  id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_id    UUID        REFERENCES users(id),
  action      VARCHAR(100) NOT NULL,
  target_type VARCHAR(50),
  target_id   VARCHAR(255),
  details     JSONB,
  ip_address  INET,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_audit_actor   ON audit_log(actor_id);
CREATE INDEX IF NOT EXISTS idx_audit_action  ON audit_log(action);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_log(created_at DESC);

-- ── objectives_progress ──────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS objectives_progress (
  id           UUID     PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      UUID     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  slot_number  SMALLINT NOT NULL REFERENCES lab_slots(slot_number),
  scenario_id  VARCHAR(100) NOT NULL,
  objective_n  SMALLINT NOT NULL,
  completed    BOOLEAN  DEFAULT FALSE,
  completed_at TIMESTAMPTZ,
  UNIQUE (user_id, slot_number, scenario_id, objective_n)
);

CREATE INDEX IF NOT EXISTS idx_obj_user ON objectives_progress(user_id);
CREATE INDEX IF NOT EXISTS idx_obj_slot ON objectives_progress(slot_number);

-- ── hints ────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS hints (
  id         UUID     PRIMARY KEY DEFAULT gen_random_uuid(),
  from_user  UUID     NOT NULL REFERENCES users(id),
  to_slot    SMALLINT NOT NULL REFERENCES lab_slots(slot_number),
  message    TEXT     NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  read_at    TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_hints_slot    ON hints(to_slot);
CREATE INDEX IF NOT EXISTS idx_hints_created ON hints(created_at DESC);

-- ── scenario_assignments ─────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS scenario_assignments (
  id           UUID     PRIMARY KEY DEFAULT gen_random_uuid(),
  slot_number  SMALLINT NOT NULL REFERENCES lab_slots(slot_number),
  scenario_id  VARCHAR(100) NOT NULL,
  assigned_by  UUID     NOT NULL REFERENCES users(id),
  assigned_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  completed    BOOLEAN  DEFAULT FALSE,
  completed_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_assign_slot ON scenario_assignments(slot_number);
